// SPDX-License-Identifier: AGPL-3.0-only
// Three WebView-facing commands, so all three are listed here and
// `tauri_plugin::Builder` autogenerates their `allow-*` / `deny-*` permissions
// under `permissions/autogenerated/`. `permissions/default.toml` then grants a
// deliberately narrow subset of them.
//
// `read_text` IS granted, and it is the one that owes an argument: it is the
// direction the desktop client deliberately refused (`src/platform/clipboardManager.ts`,
// myne#379), because a write destroys the user's clipboard while a read harvests
// whatever they last copied from a password manager. The grant is argued, with
// its cost, in `permissions/default.toml` — argued on THIS plugin rather than by
// widening the shared seam, where desktop and web would have inherited it
// silently.
const COMMANDS: &[&str] = &["write_text", "write_secret", "read_text"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS)
        .ios_path("ios")
        .android_path("android")
        .build();
}
